    internal sealed class ConstellationSavedLens
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public string Query { get; set; }
        public string KindFilter { get; set; }
        public string MissionFilter { get; set; }
        public string CreatedUtc { get; set; }
        public override string ToString(){return (Name??Id)+"   ·   query "+(Query??"∅")+"   ·   kind "+(KindFilter??"ANY")+"   ·   mission "+(MissionFilter??"ANY");}
    }
    internal sealed class ConstellationBaseline
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public string SnapshotFingerprint { get; set; }
        public string ExpeditionStoreFingerprint { get; set; }
        public int Missions { get; set; }
        public int Nodes { get; set; }
        public int Edges { get; set; }
        public int Frontiers { get; set; }
        public string CreatedUtc { get; set; }
        public override string ToString(){return (Name??Id)+"   ·   missions "+Missions+"   ·   nodes "+Nodes+"   ·   edges "+Edges+"   ·   frontiers "+Frontiers+"   ·   "+KnowledgeConstellationKernel.Short(SnapshotFingerprint);}
    }
    internal sealed class ConstellationNote
    {
        public string Id { get; set; }
        public string SubjectId { get; set; }
        public string Text { get; set; }
        public string CreatedUtc { get; set; }
        public override string ToString(){return (SubjectId??"CONSTELLATION")+"   ·   "+(Text??"");}
    }
    internal sealed class ConstellationSeal
    {
        public string Id { get; set; }
        public string SnapshotFingerprint { get; set; }
        public string StoreFingerprint { get; set; }
        public int Missions { get; set; }
        public int Nodes { get; set; }
        public int Edges { get; set; }
        public string CreatedUtc { get; set; }
        public string CertificateHash { get; set; }
        public override string ToString(){return "METAΩ SEAL   ·   missions "+Missions+"   ·   nodes "+Nodes+"   ·   edges "+Edges+"   ·   fp "+KnowledgeConstellationKernel.Short(SnapshotFingerprint);}
    }
    internal sealed class ConstellationStore
    {
        public int Schema { get; set; }
        public long Revision { get; set; }
        public string UpdatedUtc { get; set; }
        public List<ConstellationSavedLens> Lenses { get; set; }
        public List<ConstellationBaseline> Baselines { get; set; }
        public List<ConstellationNote> Notes { get; set; }
        public List<ConstellationSeal> Seals { get; set; }
        public ConstellationStore(){Schema=1;Lenses=new List<ConstellationSavedLens>();Baselines=new List<ConstellationBaseline>();Notes=new List<ConstellationNote>();Seals=new List<ConstellationSeal>();}
    }
    internal sealed class ConstellationLedgerRecord
    {
        public int Schema { get; set; }
        public long Sequence { get; set; }
        public string Utc { get; set; }
        public string Event { get; set; }
        public string Detail { get; set; }
        public string SnapshotFingerprint { get; set; }
        public string PrevHash { get; set; }
        public string EntryHash { get; set; }
        public override string ToString(){return Sequence.ToString("000000",CultureInfo.InvariantCulture)+"   ·   "+(Utc??"")+"   ·   "+(Event??"EVENT")+"   ·   "+KnowledgeConstellationKernel.Short(EntryHash);}
    }

